                ['التسليم للتوزيع', 'عدم التحميل إلا على سيارة بفحص مسجل وصالحة للنقل طبقاً لإجراء SH-006، والتحميل بنظام آخر طلبية تُحمل تُسلم أولاً.', 'سجل فحص السيارة', 'مشرف التوزيع · مشرف الحركة'],
                ['التسليم للتوزيع', 'التوقيع على بيان الحركة من الكنترول ومشرف التوزيع والسائق أو المندوب عند التسليم.', 'SH-004-F02', 'الكنترول · مشرف التوزيع · السائق'],
                ['التسليم للتوزيع', 'تسليم تقرير أخطاء التحضير اليومي لأمين المخزن، وحفظ نسخ الفواتير وبيانات الحركة.', 'SH-004-F03', 'الكنترول · مشرف التوزيع'],
            ],
        ],
        'SH-005' => [
            'title' => 'تخزين المستحضرات الصيدلية',
            'items' => [
                ['تجهيز المخزن ونظام المواقع', 'تقسيم المخزن إلى مناطق، وإعطاء كل رف كود موقع فريد (ممر-استاند-رف) وتعليق لوحة الكود عليه.', 'خريطة المخزن', 'أمين المخزن · إدارة الحاسب الآلي'],
                ['تجهيز المخزن ونظام المواقع', 'ربط كل صنف بموقعه على النظام، بحيث يُطبع كود الموقع على أذون الصرف والتسكين.', 'النظام', 'إدارة الحاسب الآلي'],
                ['تجهيز المخزن ونظام المواقع', 'تخصيص مناطق مميزة بلوحات واضحة ومنفصلة: الحجر، المرتجعات، المرفوضات، التوالف ومنتهي الصلاحية، المسحوبات، والثلاجة.', 'خريطة المخزن', 'أمين المخزن · المدير الصيدلي'],
                ['تجهيز المخزن ونظام المواقع', 'تحديد ظروف تخزين كل منطقة، والتأكد من تأهيلها بدراسة التوزيع الحراري صيفاً وشتاءً.', 'SH-023', 'المدير الصيدلي · مدير إدارة الجودة'],
                ['التسكين', 'استلام البضاعة المفرج عنها فقط من الاستلامات بإذن تحويل موقع، وأصناف الثلاجة أولاً وإدخالها الثلاجة فوراً.', 'إذن التحويل', 'أمين المخزن'],
                ['التسكين', 'تسكين كل صنف في موقعه المحدد على النظام، والأصناف التي تحتاج أقل من ١٥ درجة في غرفة التبريد، وأصناف ٢–٨ في الثلاجة.', 'النظام', 'أمين المخزن · المحضر'],
                ['التسكين', 'فصل التشغيلات المختلفة لنفس الصنف وتمييزها، ورصها بحيث تكون الأقرب انتهاءً في المقدمة أو الأعلى، وتسجيل كل تشغيلة على النظام برقمها وصلاحيتها.', 'النظام', 'المحضر'],
                ['التسكين', 'تطبيق قواعد التخزين العامة في كل مرة تسكين.', '—', 'المحضر'],
                ['التسكين', 'تسجيل أي نقل لصنف من موقع لآخر على النظام في نفس اليوم.', 'النظام', 'أمين المخزن'],
                ['مراقبة ظروف التخزين', 'تسجيل الحرارة والرطوبة لكل منطقة وثلاجة مرتين يومياً على الأقل، ومراجعة أجهزة التسجيل كل [____ ساعة]، طبقاً لإجراء SH-030.', 'سجلات SH-030', 'المحضر · أمين المخزن'],
                ['مراقبة ظروف التخزين', 'مراجعة ظروف التخزين المكتوبة على عبوات الأصناف الخاصة (الكريمات، الأقماع، الحقن، الأصناف الحساسة للضوء) والتأكد من تخزينها في المكان المناسب.', 'SH-005-F01', 'أمين المخزن (أسبوعياً) · المدير الصيدلي (شهرياً)'],
                ['متابعة الصلاحيات', 'استخراج تقرير الأصناف قريبة الانتهاء شهرياً وإرساله للمدير التجاري ومشرفي البيع لتصريفها.', 'SH-005-F02', 'إدارة الحاسب الآلي · أمين المخزن'],
                ['متابعة الصلاحيات', 'فصل أي صنف وصل للحد الأدنى للصلاحية عند الصرف عن المخزون الصالح، وإيقافه على النظام.', 'النظام', 'أمين المخزن'],
                ['متابعة الصلاحيات', 'نقل الأصناف المنتهية فور اكتشافها لمخزن التوالف ومنتهي الصلاحية وتسجيلها.', 'SH-002-F04', 'أمين المخزن'],
                ['الجرد', 'جرد عشوائي شهري لكل منطقة لعدد [____] صنف على الأقل: مطابقة الرصيد الفعلي للنظام، وجود الصنف في موقعه، الترتيب بالأقرب انتهاءً، والصلاحية.', 'SH-005-F01', 'المدير الصيدلي'],
                ['الجرد', 'عند وجود فرق: إعادة العد، والتحقيق في السبب، وعدم تعديل الرصيد إلا بمستند تسوية يعتمده المدير الصيدلي.', 'مستند التسوية', 'أمين المخزن · المدير الصيدلي'],
                ['الجرد', 'جرد كامل للمخزن مرة سنوياً على الأقل.', 'محضر الجرد السنوي', 'أمين المخزن · المدير الصيدلي · الحسابات'],
            ],
        ],
        'SH-006' => [
            'title' => 'نقل وتسليم المستحضرات الصيدلية',
            'items' => [
                ['التخطيط', 'تكويد العملاء على خطوط سير لا تتجاوز رحلتها [٢–٣] ساعات، وتوزيع الرندات على اليوم في مواعيد محددة.', 'خطة الرحلات', 'مشرف التوزيع'],
                ['التخطيط', 'توزيع السيارات والسائقين على الرندات، والتأكد من جاهزية سيارة احتياطية يومياً.', 'جدول الحركة', 'مشرف الحركة'],
                ['التخطيط', 'اختيار نوع السيارة طبقاً للأصناف: مكيفة أو معزولة لحرارة الغرفة، وصناديق تبريد أو سيارة مبردة لأصناف الثلاجة، وسيارة مبردة للنقل بين المحافظات.', 'بيان الحركة', 'مشرف التوزيع · مشرف الحركة'],
                ['قبل التحميل', 'إخلاء ساحة التحميل من سيارات التوريد، والتحقق من شخصية السائق وتسجيل السيارة عند الدخول والخروج.', 'SH-001-F01', 'موظف الأمن'],
                ['قبل التحميل', 'فحص السيارة مع السائق: النظافة، الأرضية جافة، لا حشرات أو قوارض أو انسكاب أو روائح، عمل التكييف أو التبريد، حرارة الصندوق، القفل، جهاز التتبع، سريان الترخيص ورخصة القيادة.', 'SH-006-F01', 'مشرف الحركة · السائق'],
                ['قبل التحميل', 'عدم تحميل أي سيارة غير صالحة أو بدون فحص مسجل، وتوفير السيارة الاحتياطية.', 'SH-006-F01', 'مشرف الحركة'],
                ['قبل التحميل', 'تشغيل التكييف أو التبريد قبل التحميل حتى تصل حرارة الصندوق للحدود المطلوبة.', 'SH-006-F01', 'السائق'],
                ['التحميل', 'عدّ الطلبيات والصناديق المبردة مقابل بيان الحركة، والتوقيع على الاستلام من الكنترول.', 'SH-004-F02', 'مشرف التوزيع · السائق'],
                ['التحميل', 'التحميل بحرص وبنظام آخر ما يُحمل يُسلم أولاً: الثقيل أسفل، والقابل للكسر مؤمن، والصناديق المبردة في مكان يسهل الوصول إليه وبعيداً عن مصادر الحرارة.', '—', 'السائق'],
                ['التحميل', 'إحكام غلق باب الصندوق بقفل الأمان، وتسجيل حرارة الصندوق ووقت الخروج.', 'SH-006-F02', 'المندوب · السائق'],
                ['أثناء الرحلة', 'السير على خط السير المحدد فقط، وإبقاء الصندوق مغلقاً بين العملاء، وعدم ترك السيارة دون تأمين.', '—', 'السائق'],
                ['أثناء الرحلة', 'إبقاء التكييف أو التبريد يعمل طوال الرحلة، وتسجيل حرارة الصندوق عند كل [____] عميل أو كل [____] دقيقة.', 'SH-006-F02', 'السائق'],
                ['أثناء الرحلة', 'متابعة تحرك السيارات عبر نظام تتبع المواقع، والتواصل عند التأخير أو الانحراف عن خط السير.', 'نظام التتبع', 'مشرف التوزيع'],
                ['التسليم للعميل', 'التسليم للعميل المسجل في عنوانه المرخص فقط، وتسليم أصناف الثلاجة أولاً.', 'بيان الحركة', 'المندوب'],
                ['التسليم للعميل', 'حصول التوقيع والختم على نسخة الفاتورة مع وقت التسليم، وتسجيل أي تلف أو نقص يلاحظه العميل على الفاتورة.', 'نسخة الفاتورة', 'المندوب'],
                ['التسليم للعميل', 'إبقاء الطلبيات المرفوضة أو غير المسلمة في السيارة منفصلة، واستلام المرتجعات بإشعاراتها المعتمدة فقط وفصلها عن الطلبيات (SH-002).', 'SH-002-F01', 'المندوب'],
                ['العودة', 'تسليم الفواتير الموقعة، والطلبيات غير المسلمة، والمرتجعات، وسجل حرارة الرحلة لمشرف التوزيع مقابل توقيع.', 'SH-004-F02', 'المندوب · السائق'],
                ['العودة', 'توريد التحصيلات للخزينة في نفس اليوم طبقاً لسياسة الشركة.', 'إيصالات التوريد', 'المندوب'],
                ['العودة', 'مراجعة سجل حرارة الرحلة وبيانات جهاز التسجيل، وإبلاغ المدير الصيدلي بأي انحراف.', 'SH-006-F02', 'مشرف التوزيع'],
                ['العودة', 'تسجيل قراءة العداد ووقت العودة، وإقفال بيان الحركة.', 'SH-004-F02', 'مشرف الحركة · مشرف التوزيع'],
            ],
        ],
        'SH-007' => [
            'title' => 'التعامل مع الشكاوى',
            'items' => [
                ['الاستلام والتسجيل', 'تسجيل الشكوى فور استلامها (تليفونياً أو كتابياً أو إلكترونياً أو عن طريق المندوب): بيانات العميل ووسيلة التواصل وتفاصيل الشكوى، وللمنتج: الصنف والتركيز والتشغيلة والصلاحية ورقم الفاتورة.', 'SH-007-F01', 'متلقي الشكوى'],
                ['الاستلام والتسجيل', 'تحويل الشكوى لإدارة الجودة في نفس اليوم، وإعطاؤها رقماً مسلسلاً وتسجيلها في سجل الشكاوى.', 'SH-007-F03', 'متلقي الشكوى · مدير إدارة الجودة'],
                ['الاستلام والتسجيل', 'في شكاوى المنتج: طلب احتفاظ العميل بالعينة أو استلامها بإشعار مرتجع (SH-002)، وحفظها في الحجر بملصق «شكوى · ممنوع الصرف».', 'SH-002-F01', 'المندوب · مسؤول المرتجعات'],
                ['التصنيف وتحديد الأولوية', 'تصنيف الشكوى: جودة منتج، اشتباه في غش، أثر جانبي، خدمة توزيع (تأخير، تلف، خطأ تحضير)، أو تجارية (سعر، فاتورة، تحصيل).', 'SH-007-F01', 'مدير إدارة الجودة · المدير الصيدلي'],
                ['التصنيف وتحديد الأولوية', 'تحديد الأولوية: حرجة عند احتمال خطر على المريض (اشتباه غش، تلوث، صنف أو تركيز خطأ وصل للمريض، صنف ثلاجة تعرض للحرارة)، وإلا رئيسية أو ثانوية، وتحديد المسؤول وموعد الإغلاق.', 'SH-007-F01', 'مدير إدارة الجودة · المدير الصيدلي'],
                ['الإجراءات الفورية لشكاوى المنتج', 'مراجعة باقي كمية نفس التشغيلة في المخزن، وحجزها وإيقافها على النظام عند وجود خطر محتمل.', 'النظام', 'المدير الصيدلي'],
                ['الإجراءات الفورية لشكاوى المنتج', 'الاشتباه في الغش: التعامل طبقاً لإجراء SH-011. احتمال سحب التشغيلة من السوق: التعامل طبقاً لإجراء SH-010. وإبلاغ المورد أو الشركة المصنعة في الحالتين.', 'SH-007-F02', 'المدير الصيدلي'],
                ['الإجراءات الفورية لشكاوى المنتج', 'الأثر الجانبي: إبلاغ الشركة المصنعة والمركز المصري لليقظة الدوائية بهيئة الدواء خلال المدة المحددة [____]، وتسجيل الإبلاغ.', 'SH-007-F02', 'المدير الصيدلي'],
                ['التحقيق والإجراء التصحيحي', 'إبلاغ المسؤول عن الشكوى (رئيس القسم المعني) وتوقيعه بالعلم.', 'SH-007-F02', 'مدير إدارة الجودة'],
                ['التحقيق والإجراء التصحيحي', 'تحديد السبب الجذري بمراجعة المستندات المرتبطة (الفاتورة، تقرير أخطاء التحضير، بيان الحركة، سجلات الحرارة، سجل الاستلام).', 'SH-007-F02', 'المسؤول عن الشكوى'],
                ['التحقيق والإجراء التصحيحي', 'تحديد الإجراءات التصحيحية والوقائية بمسؤول وموعد لكل إجراء، وفتح إجراء تصحيحي رسمي طبقاً لإجراء SH-008 عند تكرار الشكوى أو وجود سبب في النظام.', 'SH-007-F02', 'المسؤول عن الشكوى · مدير إدارة الجودة'],
                ['الرد والإغلاق والمتابعة', 'الرد على العميل بنتيجة الشكوى والإجراء المتخذ، وتنفيذ التصحيح التجاري إن لزم (استبدال، أو إشعار خصم بعد مرتجع طبقاً لإجراء SH-002).', 'SH-007-F02', 'مشرف البيع / مدير بيع الجملة'],
                ['الرد والإغلاق والمتابعة', 'التحقق من تنفيذ الإجراءات في مواعيدها ومن رضا العميل، ثم إغلاق الشكوى في السجل.', 'SH-007-F02 · F03', 'مدير إدارة الجودة'],
                ['الرد والإغلاق والمتابعة', 'تحليل الشكاوى شهرياً حسب النوع والعميل والصنف والقسم، وعرض النتائج في مراجعة الإدارة.', 'تقرير الاتجاهات', 'مدير إدارة الجودة'],
            ],
        ],
        'SH-008' => [
            'title' => 'الإجراءات التصحيحية والوقائية',
            'items' => [
                ['الإبلاغ والتسجيل', 'الإبلاغ عن الانحراف فور اكتشافه للرئيس المباشر، وتسجيله على تقرير الانحراف بوصف ما حدث ومكانه ووقته والمنتجات المتأثرة.', 'SH-008-F01', 'مكتشف الانحراف'],
                ['الإبلاغ والتسجيل', 'اتخاذ التصحيح الفوري لاحتواء الأثر (مثل حجز البضاعة أو إيقاف الصرف) وتسجيله.', 'SH-008-F01', 'رئيس القسم المعني'],
                ['الإبلاغ والتسجيل', 'استلام التقرير في نفس اليوم، وإعطاؤه رقماً مسلسلاً وتسجيله في سجل الإجراءات.', 'SH-008-F04', 'مدير إدارة الجودة'],
                ['التصنيف وتقييم الأثر', 'تصنيف الانحراف (حرج، رئيسي، ثانوي) وتحديد موعد تقديم الخطة.', 'SH-008-F01', 'مدير إدارة الجودة · المدير الصيدلي'],
                ['التصنيف وتقييم الأثر', 'تقييم أثر الانحراف على المنتجات والعملاء، والقرار في البضاعة المتأثرة، وتحديد الحاجة لإبلاغ هيئة الدواء أو المورد.', 'SH-008-F01', 'المدير الصيدلي'],
                ['التحقيق في السبب الجذري', 'تشكيل فريق التحقيق من مدير إدارة الجودة ورئيس القسم المعني ومن يلزم.', 'SH-008-F02', 'مدير إدارة الجودة'],
                ['التحقيق في السبب الجذري', 'جمع المستندات والبيانات المرتبطة، وتحديد السبب الجذري بأداة مناسبة (لماذا الخمسة، أو مخطط السبب والنتيجة)، ومراجعة تكرار انحرافات مشابهة في السجل.', 'SH-008-F02', 'فريق التحقيق'],
                ['خطة الإجراءات والتنفيذ', 'وضع الإجراءات التصحيحية والوقائية، لكل إجراء: المسؤول، والموعد، والدليل المطلوب على التنفيذ، ومعيار قياس الفاعلية.', 'SH-008-F02', 'فريق التحقيق'],
                ['خطة الإجراءات والتنفيذ', 'اعتماد الخطة، وإذا تطلبت تعديل إجراء أو نموذج أو نظام يتم ذلك من خلال إجراء التحكم في التغيير (SH-027)، والتدريب على التعديل.', 'SH-008-F02', 'مدير إدارة الجودة · المدير الصيدلي'],
                ['خطة الإجراءات والتنفيذ', 'تنفيذ الإجراءات في مواعيدها، وتقديم دليل التنفيذ لإدارة الجودة.', 'SH-008-F02', 'المسؤول عن الإجراء'],
                ['خطة الإجراءات والتنفيذ', 'متابعة المواعيد أسبوعياً، وتصعيد أي إجراء متأخر لرئيس القسم ثم للمدير العام.', 'SH-008-F04', 'مدير إدارة الجودة'],
                ['التحقق من الفاعلية والإغلاق', 'التحقق من الفاعلية بعد المدة المحددة باستخدام المعيار المحدد في الخطة.', 'SH-008-F03', 'مدير إدارة الجودة · المدير الصيدلي'],
                ['التحقق من الفاعلية والإغلاق', 'إذا كان الإجراء فعالاً: إغلاق الانحراف في السجل. إذا لم يكن فعالاً: إعادة التحقيق في السبب، ووضع إجراءات جديدة بمواعيد جديدة.', 'SH-008-F03 · F04', 'مدير إدارة الجودة'],
                ['المراجعة الدورية', 'مراجعة نصف سنوية لموقف كل الإجراءات: المنتهية بفاعلية، والمتأخرة، والأسباب الجذرية المتكررة، والاتجاهات حسب القسم والمصدر.', 'محضر مراجعة الإدارة', 'الرئيس التنفيذي · مدير إدارة الجودة · المدير الصيدلي · مديرو الأقسام'],
                ['المراجعة الدورية', 'تسجيل قرارات المراجعة في محضر اجتماع، ومتابعة تنفيذها.', 'محضر مراجعة الإدارة', 'مدير إدارة الجودة'],
            ],
        ],
        'SH-009' => [
            'title' => 'إدارة مخاطر الجودة',
            'items' => [
                ['البدء', 'تحديد موضوع التقييم وسببه: عملية جديدة، تغيير (SH-027)، انحراف أو شكوى متكررة، تفتيش، مورد جديد، أو المراجعة السنوية.', 'SH-009-F01', 'مدير إدارة الجودة'],
                ['البدء', 'تشكيل فريق التقييم (الجودة، المدير الصيدلي، القسم المعني)، وتجميع البيانات المتاحة، وتحديد الجدول الزمني.', 'SH-009-F01', 'مدير إدارة الجودة'],
                ['تحديد المخاطر', 'مراجعة خطوات العملية خطوة بخطوة، وحصر كل مصادر الخطر المحتملة وما قد ينتج عنها من ضرر على المنتج أو المريض أو الالتزام.', 'SH-009-F01', 'فريق التقييم'],
                ['التحليل والتقييم', 'إعطاء درجة لاحتمالية الحدوث ودرجة لشدة الخطورة لكل خطر طبقاً للمقاييس المعتمدة، وحساب رقم أولوية الخطر.', 'SH-009-F01', 'فريق التقييم'],
                ['التحليل والتقييم', 'تحديد مستوى كل خطر (A، B، C)، وترتيب المخاطر من الأعلى للأقل، وتسجيلها في سجل المخاطر.', 'SH-009-F02', 'مدير إدارة الجودة'],
                ['التحكم في المخاطر', 'اختيار طريقة التحكم المناسبة: إيقاف النشاط عالي الخطورة، إزالة المصدر، تقليل الاحتمالية، تقليل العواقب، مشاركة الخطر مع طرف آخر بعقد، أو قبوله بقرار مسجل.', 'SH-009-F02', 'فريق التقييم · المدير الصيدلي'],
                ['التحكم في المخاطر', 'تحديد الإجراءات لكل خطر بمسؤول وموعد طبقاً لمهلة مستواه، وتحديد ما يجب عمله مسبقاً إذا تحقق الخطر.', 'SH-009-F02', 'فريق التقييم'],
                ['التحكم في المخاطر', 'تنفيذ الإجراءات من خلال الإجراءات التصحيحية والوقائية (SH-008)، أو التحكم في التغيير (SH-027) عند تعديل إجراء أو نظام.', 'SH-008 · SH-027', 'المسؤول عن الإجراء'],
                ['التحكم في المخاطر', 'قبول الخطر المتبقي: المستوى A بقرار الرئيس التنفيذي، والمستوى B بقرار مدير إدارة الجودة والمدير الصيدلي، والمستوى C بقرار رئيس القسم.', 'SH-009-F02', 'حسب المستوى'],
                ['المتابعة والمراجعة والتواصل', 'متابعة تنفيذ الإجراءات في مواعيدها، وإعادة تقييم الخطر المتبقي بنفس المقاييس بعد التنفيذ.', 'SH-009-F03', 'مدير إدارة الجودة'],
                ['المتابعة والمراجعة والتواصل', 'إعادة التقييم عند حدوث تغيير أو انحراف أو ظهور معلومات جديدة، وإعادة تقييم السجل بالكامل في نهاية كل عام.', 'SH-009-F02', 'مدير إدارة الجودة · فريق التقييم'],
                ['المتابعة والمراجعة والتواصل', 'إبلاغ الأقسام المعنية بالمخاطر وإجراءاتها، وعرض المخاطر من المستوى A وحالتها في مراجعة الإدارة.', 'محضر مراجعة الإدارة', 'مدير إدارة الجودة'],
                ['الفرص', 'تحديد فرص التحسين التي تظهر أثناء التقييم، والإجراءات والموارد اللازمة لها، وتسجيلها، وتقييم فاعليتها بعد التنفيذ.', 'SH-009-F04', 'مدير إدارة الجودة · مديرو الإدارات'],
            ],
        ],
        'SH-010' => [
            'title' => 'الاستدعاء والسحب من السوق',
            'items' => [
                ['الاستلام والتقييم', 'متابعة منشورات هيئة الدواء وإخطارات الموردين يومياً، وتحويل أي منشور سحب للمدير الصيدلي فور صدوره.', 'SH-010-F01', 'مسؤول المشتريات'],
                ['الاستلام والتقييم', 'تسجيل المنشور في السجل، وتحديد الصنف والتشغيلات ودرجة الاستدعاء والمدة المطلوبة.', 'SH-010-F01', 'المدير الصيدلي'],
                ['الاستلام والتقييم', 'البحث في النظام عن أي وارد من التشغيلة خلال [سنتين] على الأقل، واستخراج كل حركاتها (الوارد، المبيعات لكل عميل، الرصيد).', 'تقرير النظام', 'مراقبة المخزون'],
                ['الإيقاف داخل المخزن', 'إيقاف التشغيلة على النظام فوراً ونقلها لفئة «مسحوب»، وإخفاؤها من شاشة المبيعات.', 'النظام', 'مراقبة المخزون'],
                ['الإيقاف داخل المخزن', 'المرور الفعلي على كل الرفوف والثلاجات ومناطق الطلبيات المجهزة والمرتجعات، وجمع كل عبوات التشغيلة ونقلها لمنطقة المسحوبات بملصق «مسحوب · ممنوع الصرف».', 'SH-010-F03', 'أمين المخزن'],
                ['الإيقاف داخل المخزن', 'سحب أي كمية من التشغيلة داخل طلبيات مجهزة لم تخرج بعد، ومراجعة الوارد ومنطقة الحجر ورفض أي شحنة منها.', 'SH-010-F03', 'أمين المخزن · أمين مخزن الاستلام'],
                ['إبلاغ العملاء', 'إعداد قائمة كل العملاء الذين اشتروا التشغيلة بالكميات وبيانات الاتصال من فواتير البيع.', 'SH-010-F02', 'مراقبة المخزون · المدير الصيدلي'],
                ['إبلاغ العملاء', 'الاتصال بكل عميل في المدة المحددة لإبلاغه بقرار السحب وطلب تجنيب الكمية لديه، ثم إرسال إخطار مكتوب (رسالة أو خطاب) بالصنف والتشغيلة والسبب، وتسجيل وقت ووسيلة الاتصال والكمية لدى العميل.', 'SH-010-F02', 'التلي سيلز · مشرفو البيع'],
                ['إبلاغ العملاء', 'متابعة كل عميل لم يتم الوصول إليه بزيارة المندوب، وإبلاغ المدير الصيدلي بأي عميل لم يتم الوصول إليه في المدة.', 'SH-010-F02', 'مشرفو البيع · المندوبون'],
                ['الاسترجاع', 'استرجاع الكميات من العملاء بإشعار مرتجع مميز «استدعاء» (SH-002-F01)، ونقلها منفصلة عن الطلبيات وفي ظروف تخزينها.', 'SH-002-F01', 'المندوبون · مشرف التوزيع'],
                ['الاسترجاع', 'استلام الكميات المسترجعة مباشرة في منطقة المسحوبات دون المرور بالمخزون الصالح، وتسجيلها.', 'SH-010-F02', 'أمين المخزن'],
                ['الاسترجاع', 'إصدار إشعارات الخصم للعملاء طبقاً لقرار المدير الصيدلي.', 'إشعار الخصم', 'محاسب العملاء'],
                ['التسوية والتصرف والإغلاق', 'تسوية السحب: الكمية المستلمة من التشغيلة = الكمية الموجودة بالمخزن + المسترجعة من العملاء + غير المسترجعة، وتحديد نسبة نجاح السحب.', 'SH-010-F03', 'المدير الصيدلي'],
                ['التسوية والتصرف والإغلاق', 'التصرف في الكميات المسحوبة طبقاً لتعليمات هيئة الدواء أو المصنع فقط: إرجاعها للمورد بمستند، أو إعدامها بمحضر.', 'SH-010-F03', 'المدير الصيدلي · مسؤول المشتريات'],
                ['التسوية والتصرف والإغلاق', 'إبلاغ هيئة الدواء والمصنع بنتيجة السحب والكميات طبقاً لما يطلبه المنشور، وحفظ صورة الإبلاغ.', 'SH-010-F03', 'المدير الصيدلي'],
                ['التسوية والتصرف والإغلاق', 'إغلاق السحب في السجل بعد التسوية والتصرف، وفتح إجراء تصحيحي (SH-008) لأي ثغرة ظهرت.', 'SH-010-F01', 'المدير الصيدلي · مدير إدارة الجودة'],
                ['السحب الوهمي السنوي', 'اختيار صنف وتشغيلة حقيقية مباعة لعدد كافٍ من العملاء، وبدء سحب وهمي دون إبلاغ الأقسام مسبقاً بأنه وهمي إلا بعد انتهائه [حسب سياسة الشركة].', 'SH-010-F04', 'مدير إدارة الجودة · المدير الصيدلي'],
                ['السحب الوهمي السنوي', 'قياس نسبة العملاء الذين تم الوصول إليهم خلال [٣] ساعات وفي نهاية اليوم، ونسبة دقة بيانات التشغيلة والكميات، ومقارنتها بالمستهدف [١٠٠٪ خلال ٢٤ ساعة].', 'SH-010-F04', 'مدير إدارة الجودة'],
                ['السحب الوهمي السنوي', 'معالجة أي ثغرة بإجراء تصحيحي، وتسجيل النتيجة وعرضها في مراجعة الإدارة.', 'SH-010-F04 · SH-008', 'مدير إدارة الجودة'],
            ],
        ],
        'SH-011' => [
