                ['المنع', 'الشراء من موردين مرخصين ومعتمدين ومسجلين بالنظام فقط، وبفاتورة رسمية، مع الحذر الإضافي عند الشراء من المخازن والوكلاء وعند العروض بأسعار أقل بكثير من السوق.', 'أمر الشراء', 'مسؤول المشتريات'],
                ['المنع', 'متابعة منشورات الغش التجاري يومياً، وتسجيل كل منشور بالصنف والتشغيلة والمواصفات المميزة.', 'SH-011-F01', 'مسؤول المشتريات · المدير الصيدلي'],
                ['المنع', 'مراجعة كل منشور مقابل الوارد والمخزون فعلياً على الرفوف، والتوقيع على المراجعة خلال [٢٤ ساعة].', 'SH-011-F01', 'أمين مخزن الاستلام · أمين المخزن'],
                ['المنع', 'تدريب كل من يتعامل مع المستحضرات على علامات الاشتباه، وتوفير العبوات المرجعية للأصناف عالية الخطورة.', 'SHY-154', 'مدير إدارة الجودة'],
                ['الاكتشاف', 'فحص كل شحنة واردة ومرتجع مقابل علامات الاشتباه ومنشورات الغش، والتأكد أن المرتجع بيع من المخزن بنفس التشغيلة والصلاحية.', 'SH-001-F02 · SH-002-F02', 'أمين مخزن الاستلام · مسؤول المرتجعات'],
                ['الاكتشاف', 'الإبلاغ الفوري عن أي عبوة مشتبه فيها تظهر أثناء التخزين أو التحضير أو المراجعة، وعدم صرفها.', 'SH-011-F02', 'المحضرون · الكنترول · أمين المخزن'],
                ['الاكتشاف', 'تحويل أي شكوى عميل تشير لاحتمال غش للمدير الصيدلي في نفس اليوم (SH-007).', 'SH-007-F01', 'مدير إدارة الجودة'],
                ['العزل والتأمين', 'عزل المستحضر المشتبه فيه فوراً في منطقة العزل المغلقة بملصق «مشتبه · ممنوع الصرف أو التخزين». في الاستلام: رفض الشحنة وعدم إدخالها على المخزون أو النظام مع عزلها.', 'SH-011-F03', 'أمين المخزن · أمين مخزن الاستلام'],
                ['العزل والتأمين', 'إيقاف التشغيلة على النظام كاملة، وجمع أي عبوات أخرى منها من الرفوف والطلبيات المجهزة.', 'النظام', 'المدير الصيدلي · مراقبة المخزون'],
                ['العزل والتأمين', 'تسجيل الكميات المعزولة وحفظ الفواتير والمستندات الأصلية وصور العبوات.', 'SH-011-F02 · F03', 'المدير الصيدلي'],
                ['الإبلاغ', 'تقييم الاشتباه ومقارنة العبوة بالعبوة المرجعية، وتسجيل نتيجة التقييم.', 'SH-011-F02', 'المدير الصيدلي'],
                ['الإبلاغ', 'إبلاغ هيئة الدواء المصرية على النموذج المعتمد خلال [٢٤ ساعة] من الاشتباه، وإرسال العينات عند الطلب.', 'SH-011-F02', 'المدير الصيدلي'],
                ['الإبلاغ', 'مخاطبة المورد والشركة المصنعة كتابياً بالبريد الإلكتروني وبأي وسيلة سريعة، دون إعادة البضاعة لهم.', 'SH-011-F02', 'المدير الصيدلي · مسؤول المشتريات'],
                ['الإبلاغ', 'إيقاف التعامل مع المورد مصدر المستحضر لحين انتهاء التحقيق.', 'قائمة الموردين', 'المدير التجاري'],
                ['التتبع والسحب', 'تتبع مصدر المستحضر من فواتير الشراء، ومراجعة أي تشغيلات أخرى من نفس المورد.', 'SH-011-F02', 'المدير الصيدلي · مسؤول المشتريات'],
                ['التتبع والسحب', 'تحديد العملاء الذين استلموا نفس التشغيلة، وبدء الاستدعاء طبقاً لإجراء SH-010 فوراً إذا كان المستحضر قد بيع، أو عند صدور قرار هيئة الدواء.', 'SH-010-F02', 'المدير الصيدلي'],
